43	/**
44	 * Added at the very end of every premium, after all percentage modifiers, so
45	 * no surcharge or discount is ever computed on top of it.
46	 */
47	const PROCESSING_FEE = 5;
48	
49	/**
50	 * Rates are kept as exact numerator/denominator fractions rather than float
51	 * multipliers (10 / 100, never 1.1) so intermediate amounts stay exact and
52	 * only the final premium is rounded.
53	 */
54	const percent = (amount: number, rate: number): number => (amount * rate) / 100;
55	
56	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
57	
58	const BASE_PREMIUMS: Record<string, number> = {
59	  sword: 100,
60	  amulet: 60,
61	  staff: 80,
62	  potion: 40,
63	  rune: 25,
64	  moonstone: 25,
65	};
66	
67	/** A building block of 3 alike components is offered at this base premium. */
68	const COMPONENT_BLOCK_BASE_PREMIUM = 60;
69	const COMPONENT_BLOCK_SIZE = 3;
70	
71	/**
72	 * Knowingly incomplete: only recognises a block when the *whole* quote is
73	 * exactly 3 runes. Grouping by component type, and blocks alongside other
74	 * items, are not driven by a test yet.
75	 */
76	const formsComponentBlock = (items: Item[]): boolean =>
77	  items.length === COMPONENT_BLOCK_SIZE &&
78	  items.every((item) => item.type === "rune");
79	
80	const sumOfItemPremiums = (items: Item[]): number =>
81	  items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
82	
83	export const runScenario = (scenario: Scenario): ScenarioResult => {
84	  const quote = scenario.steps[0] as QuoteStep;
85	  const basePremium = formsComponentBlock(quote.items)
86	    ? COMPONENT_BLOCK_BASE_PREMIUM
87	    : sumOfItemPremiums(quote.items);
88	  const modifiedPremium =
89	    basePremium + percent(basePremium, FIRST_INSURANCE_SURCHARGE_PERCENT);
90	  return {
91	    results: [{ premium: Math.ceil(modifiedPremium + PROCESSING_FEE) }],
92	  };
93	};
